/**
 * Verifies that `projectId` belongs to `studioId` before any write.
 * Returns `{ ok: true }` when the project is found, `{ ok: false, error }` otherwise.
 * Mirrors the inline check in `updateProjectStatusAction` (line ~461).
 */
async function verifyProjectInStudio(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  projectId: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const { data, error } = await supabase
    .from('projects')
    .select('id')
    .eq('id', projectId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    return { ok: false, error: 'Project not found' }
  }
  return { ok: true }
}

