/**
 * Pure deposit-pool helpers — no DB, no React.
 * Used by components and unit tests.
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type DepositPillVariant =
  | 'green-pool'
  | 'amber-pending'
  | 'indigo-applied'
  | 'green-paid-full'
  | 'amber-stalled'

export interface DepositPillState {
  variant: DepositPillVariant
  label: string
}

export interface DepositPillInput {
  pool_cents: number
  applied_cents: number
  status: string
  sessions_completed: number
  total_sessions_planned: number | null
  stalled_at: string | null
}

export interface PoolBalance {
  /** Total received deposit */
  total: number
  /** Amount applied to sessions */
  applied: number
  /** Remaining = total - applied */
  remaining: number
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function stalledDays(stalledAt: string): number {
  const ms = Date.now() - new Date(stalledAt).getTime()
  return Math.floor(ms / (1000 * 60 * 60 * 24))
}

/**
 * Determine the deposit pill state from raw project fields.
 * No side effects, no async — pure logic.
 */
export function getDepositPillState(input: DepositPillInput): DepositPillState {
  const {
    pool_cents,
    applied_cents,
    status,
    sessions_completed,
    total_sessions_planned,
    stalled_at,
  } = input

  // Stalled takes highest priority
  if (stalled_at) {
    const days = stalledDays(stalled_at)
    return {
      variant: 'amber-stalled',
      label: `Stalled ${days}d`,
    }
  }

  // Completed or healing + all sessions done = paid in full
  const isTerminalStatus = status === 'completed' || status === 'healing'
  const allSessionsDone =
    total_sessions_planned !== null && sessions_completed >= total_sessions_planned

  if (isTerminalStatus && allSessionsDone) {
    return { variant: 'green-paid-full', label: 'Paid in full' }
  }

  // Pool fully applied
  if (pool_cents > 0 && applied_cents >= pool_cents) {
    return { variant: 'indigo-applied', label: 'Pool applied' }
  }

  // Pool has funds remaining
  if (pool_cents > 0) {
    const dollars = (pool_cents / 100).toLocaleString('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    })
    return { variant: 'green-pool', label: `${dollars} in pool` }
  }

  // No pool yet
  return { variant: 'amber-pending', label: 'Deposit pending' }
}

/**
 * Break pool_cents into the three balance components.
 */
export function formatPoolBalance(pool_cents: number, applied_cents: number): PoolBalance {
  const safePool = Math.max(0, pool_cents)
  const safeApplied = Math.max(0, Math.min(applied_cents, safePool))
  return {
    total: safePool,
    applied: safeApplied,
    remaining: safePool - safeApplied,
  }
}

/**
 * Project status machine — pure transition logic.
 * Mirrors the allow-list enforced by the `advance_project_status` RPC.
 * No DB, no React — safe for unit tests.
 */

import type { ProjectStatus } from '@/lib/supabase/types'

// ─── Allowed transition map ───────────────────────────────────────────────────
//
// Every key is a "from" status; the Set value lists every reachable "to" status.
// "cancelled" is the archive state — reachable from any status.

const ALLOWED: Record<ProjectStatus, Set<ProjectStatus>> = {
  planning: new Set<ProjectStatus>(['deposit_paid', 'active', 'on_hold', 'cancelled']),
  deposit_paid: new Set<ProjectStatus>(['active', 'on_hold', 'cancelled']),
  active: new Set<ProjectStatus>(['healing', 'completed', 'on_hold', 'cancelled']),
  healing: new Set<ProjectStatus>(['active', 'completed', 'on_hold', 'cancelled']),
  completed: new Set<ProjectStatus>(['cancelled']),
  on_hold: new Set<ProjectStatus>(['planning', 'deposit_paid', 'active', 'cancelled']),
  cancelled: new Set<ProjectStatus>([]),
}

/**
 * Returns true if transitioning `from` → `to` is a valid project status move.
 * A status is allowed to "stay" at itself (returns true).
 */
export function isTransitionAllowed(from: ProjectStatus, to: ProjectStatus): boolean {
  if (from === to) return true
  return ALLOWED[from]?.has(to) ?? false
}

/**
 * Returns the list of statuses reachable from `current`.
 * Does NOT include the current status itself.
 */
export function getReachableStatuses(current: ProjectStatus): ProjectStatus[] {
  return Array.from(ALLOWED[current] ?? [])
}

export { type ProjectStatus }

/**
 * Photo slot helpers — pure, no DB, no React.
 * Slot order: before_skin, reference, then per-session pairs (fresh_N, healed_N).
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type SlotKind = 'before' | 'reference' | 'fresh' | 'healed'

export interface ParsedSlotType {
  kind: SlotKind
  session_number: number | null
}

// ─── Slot list generation ─────────────────────────────────────────────────────

/**
 * Generate the ordered list of slot_type strings for a project.
 *
 * Slot order:
 *   1. "before_skin"
 *   2. "reference"
 *   3. For each session 1..N: "fresh_{n}", "healed_{n}"
 *
 * If `totalSessionsPlanned` is null/0, only the two base slots are generated.
 */
export function getSlotList(totalSessionsPlanned: number | null): string[] {
  const slots: string[] = ['before_skin', 'reference']
  const n = totalSessionsPlanned ?? 0
  for (let i = 1; i <= n; i++) {
    slots.push(`fresh_${i}`)
    slots.push(`healed_${i}`)
  }
  return slots
}

/**
 * Parse a slot_type string into a structured object.
 *
 * Examples:
 *   "before_skin" → { kind: 'before', session_number: null }
 *   "reference"   → { kind: 'reference', session_number: null }
 *   "fresh_3"     → { kind: 'fresh', session_number: 3 }
 *   "healed_2"    → { kind: 'healed', session_number: 2 }
 */
export function parseSlotType(slot_type: string): ParsedSlotType {
  if (slot_type === 'before_skin') {
    return { kind: 'before', session_number: null }
  }
  if (slot_type === 'reference') {
    return { kind: 'reference', session_number: null }
  }
  const freshMatch = /^fresh_(\d+)$/.exec(slot_type)
  if (freshMatch) {
    return { kind: 'fresh', session_number: parseInt(freshMatch[1], 10) }
  }
  const healedMatch = /^healed_(\d+)$/.exec(slot_type)
  if (healedMatch) {
    return { kind: 'healed', session_number: parseInt(healedMatch[1], 10) }
  }
  // Unknown — treat as reference-equivalent
  return { kind: 'reference', session_number: null }
}

/**
 * Compute the expected "healed" photo due date from a session date.
 * Tattoos are typically assessed 6 weeks post-session.
 */
export function computeHealedDueDate(sessionDate: Date): Date {
  const due = new Date(sessionDate)
  due.setDate(due.getDate() + 42) // 6 weeks = 42 days
  return due
}

/**
 * Unit tests — deposit pool logic
 * Tests pure helpers from lib/projects/deposit.ts — no DB, no network.
 */

import { describe, it, expect } from 'vitest'
import {
  getDepositPillState,
  formatPoolBalance,
} from '@/lib/projects/deposit'

// ─── getDepositPillState ──────────────────────────────────────────────────────

describe('getDepositPillState', () => {
  const base = {
    pool_cents: 0,
    applied_cents: 0,
    status: 'planning',
    sessions_completed: 0,
    total_sessions_planned: null,
    stalled_at: null,
  }

  it('green-pool: pool > 0, not all applied', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 15000,
      applied_cents: 0,
      status: 'active',
    })
    expect(result.variant).toBe('green-pool')
    expect(result.label).toContain('$150')
  })

  it('amber-pending: pool = 0, status = planning', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 0,
      status: 'planning',
    })
    expect(result.variant).toBe('amber-pending')
    expect(result.label).toBe('Deposit pending')
  })

  it('indigo-applied: applied >= pool, pool > 0', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 10000,
      applied_cents: 10000,
      status: 'active',
    })
    expect(result.variant).toBe('indigo-applied')
    expect(result.label).toBe('Pool applied')
  })

  it('indigo-applied: applied > pool (over-applied edge case)', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 10000,
      applied_cents: 12000,
      status: 'active',
    })
    expect(result.variant).toBe('indigo-applied')
  })

  it('green-paid-full: sessions_completed = total, status = completed', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 20000,
      applied_cents: 20000,
      status: 'completed',
      sessions_completed: 5,
      total_sessions_planned: 5,
    })
    expect(result.variant).toBe('green-paid-full')
    expect(result.label).toBe('Paid in full')
  })

  it('green-paid-full: status = healing, all sessions done', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 10000,
      applied_cents: 10000,
      status: 'healing',
      sessions_completed: 3,
      total_sessions_planned: 3,
    })
    expect(result.variant).toBe('green-paid-full')
    expect(result.label).toBe('Paid in full')
  })

  it('NOT green-paid-full when sessions not completed', () => {
    const result = getDepositPillState({
      ...base,
      pool_cents: 10000,
      applied_cents: 10000,
      status: 'healing',
      sessions_completed: 2,
      total_sessions_planned: 3,
    })
    // Not all sessions done — falls back to indigo-applied
    expect(result.variant).toBe('indigo-applied')
  })

  it('amber-stalled: stalled_at set overrides everything', () => {
    const stalledAt = new Date(Date.now() - 10 * 24 * 60 * 60 * 1000).toISOString() // 10 days ago
    const result = getDepositPillState({
      ...base,
      pool_cents: 20000,
      applied_cents: 20000,
      status: 'completed',
      sessions_completed: 5,
      total_sessions_planned: 5,
      stalled_at: stalledAt,
    })
    expect(result.variant).toBe('amber-stalled')
    expect(result.label).toMatch(/Stalled \d+d/)
    expect(result.label).toContain('10d')
  })

  it('stalled label shows 0d when stalled today', () => {
    const stalledAt = new Date().toISOString()
    const result = getDepositPillState({
      ...base,
      stalled_at: stalledAt,
    })
    expect(result.variant).toBe('amber-stalled')
    expect(result.label).toBe('Stalled 0d')
  })
})

// ─── formatPoolBalance ────────────────────────────────────────────────────────

describe('formatPoolBalance', () => {
  it('returns zero balances for empty pool', () => {
    const b = formatPoolBalance(0, 0)
    expect(b.total).toBe(0)
    expect(b.applied).toBe(0)
    expect(b.remaining).toBe(0)
  })

  it('computes remaining correctly', () => {
    const b = formatPoolBalance(20000, 8000)
    expect(b.total).toBe(20000)
    expect(b.applied).toBe(8000)
    expect(b.remaining).toBe(12000)
  })

  it('clamps applied to total when over-applied', () => {
    const b = formatPoolBalance(10000, 15000)
    expect(b.applied).toBe(10000)
    expect(b.remaining).toBe(0)
  })

  it('clamps negative values to 0', () => {
    const b = formatPoolBalance(-500, -100)
    expect(b.total).toBe(0)
    expect(b.applied).toBe(0)
    expect(b.remaining).toBe(0)
  })

  it('fully applied pool has zero remaining', () => {
    const b = formatPoolBalance(5000, 5000)
    expect(b.remaining).toBe(0)
  })
})

/**
 * Unit tests — project status machine
 * Tests pure transition logic from lib/projects/status.ts — no DB.
 */

import { describe, it, expect } from 'vitest'
import { isTransitionAllowed, getReachableStatuses } from '@/lib/projects/status'
import type { ProjectStatus } from '@/lib/supabase/types'

// ─── Valid transitions ────────────────────────────────────────────────────────

describe('isTransitionAllowed — valid transitions', () => {
  const valid: Array<[ProjectStatus, ProjectStatus]> = [
    ['planning', 'deposit_paid'],
    ['planning', 'active'],
    ['planning', 'on_hold'],
    ['planning', 'cancelled'],
    ['deposit_paid', 'active'],
    ['deposit_paid', 'on_hold'],
    ['deposit_paid', 'cancelled'],
    ['active', 'healing'],
    ['active', 'completed'],
    ['active', 'on_hold'],
    ['active', 'cancelled'],
    ['healing', 'active'],
    ['healing', 'completed'],
    ['healing', 'on_hold'],
    ['healing', 'cancelled'],
    ['completed', 'cancelled'],
    ['on_hold', 'planning'],
    ['on_hold', 'deposit_paid'],
    ['on_hold', 'active'],
    ['on_hold', 'cancelled'],
  ]

  for (const [from, to] of valid) {
    it(`${from} → ${to}`, () => {
      expect(isTransitionAllowed(from, to)).toBe(true)
    })
  }
})

// ─── Invalid (rejected) transitions ──────────────────────────────────────────

describe('isTransitionAllowed — rejected transitions', () => {
  const invalid: Array<[ProjectStatus, ProjectStatus]> = [
    // Cannot skip backwards without on_hold
    ['deposit_paid', 'planning'],
    ['active', 'planning'],
    ['active', 'deposit_paid'],
    ['healing', 'planning'],
    ['healing', 'deposit_paid'],
    ['completed', 'planning'],
    ['completed', 'deposit_paid'],
    ['completed', 'active'],
    ['completed', 'healing'],
    ['completed', 'on_hold'],
    // cancelled is terminal
    ['cancelled', 'planning'],
    ['cancelled', 'deposit_paid'],
    ['cancelled', 'active'],
    ['cancelled', 'healing'],
    ['cancelled', 'completed'],
    ['cancelled', 'on_hold'],
  ]

  for (const [from, to] of invalid) {
    it(`${from} → ${to} (rejected)`, () => {
      expect(isTransitionAllowed(from, to)).toBe(false)
    })
  }
})

// ─── Identity (same status) ───────────────────────────────────────────────────

describe('isTransitionAllowed — identity (no-op)', () => {
  const statuses: ProjectStatus[] = [
    'planning', 'deposit_paid', 'active', 'healing', 'completed', 'on_hold', 'cancelled',
  ]

  for (const s of statuses) {
    it(`${s} → ${s} is always true`, () => {
      expect(isTransitionAllowed(s, s)).toBe(true)
    })
  }
})

// ─── getReachableStatuses ─────────────────────────────────────────────────────

describe('getReachableStatuses', () => {
  it('planning has 4 reachable statuses', () => {
    const r = getReachableStatuses('planning')
    expect(r).toHaveLength(4)
    expect(r).toContain('deposit_paid')
    expect(r).toContain('active')
    expect(r).toContain('on_hold')
    expect(r).toContain('cancelled')
  })

  it('completed only reaches cancelled', () => {
    const r = getReachableStatuses('completed')
    expect(r).toEqual(['cancelled'])
  })

  it('cancelled has no reachable statuses (terminal)', () => {
    const r = getReachableStatuses('cancelled')
    expect(r).toHaveLength(0)
  })

  it('on_hold can return to planning, deposit_paid, active', () => {
    const r = getReachableStatuses('on_hold')
    expect(r).toContain('planning')
    expect(r).toContain('deposit_paid')
    expect(r).toContain('active')
    expect(r).toContain('cancelled')
  })
})

/**
 * Unit tests — photo slot helpers
 * Tests pure functions from lib/projects/slots.ts — no DB.
 */

import { describe, it, expect } from 'vitest'
import { getSlotList, parseSlotType, computeHealedDueDate } from '@/lib/projects/slots'

// ─── getSlotList ──────────────────────────────────────────────────────────────

describe('getSlotList', () => {
  it('null sessions → only base slots [before_skin, reference]', () => {
    const slots = getSlotList(null)
    expect(slots).toEqual(['before_skin', 'reference'])
  })

  it('0 sessions → only base slots', () => {
    const slots = getSlotList(0)
    expect(slots).toEqual(['before_skin', 'reference'])
  })

  it('1 session → 4 slots: before, reference, fresh_1, healed_1', () => {
    const slots = getSlotList(1)
    expect(slots).toEqual(['before_skin', 'reference', 'fresh_1', 'healed_1'])
  })

  it('5 sessions → 12 slots (2 base + 10 session slots)', () => {
    const slots = getSlotList(5)
    expect(slots).toHaveLength(12)
    expect(slots[0]).toBe('before_skin')
    expect(slots[1]).toBe('reference')
    expect(slots[2]).toBe('fresh_1')
    expect(slots[3]).toBe('healed_1')
    expect(slots[4]).toBe('fresh_2')
    expect(slots[5]).toBe('healed_2')
    expect(slots[10]).toBe('fresh_5')
    expect(slots[11]).toBe('healed_5')
  })

  it('each session produces exactly one fresh and one healed slot', () => {
    const slots = getSlotList(3)
    const freshSlots = slots.filter((s) => s.startsWith('fresh_'))
    const healedSlots = slots.filter((s) => s.startsWith('healed_'))
    expect(freshSlots).toHaveLength(3)
    expect(healedSlots).toHaveLength(3)
  })

  it('slots alternate fresh/healed per session', () => {
    const slots = getSlotList(2)
    // Index 2 = fresh_1, 3 = healed_1, 4 = fresh_2, 5 = healed_2
    expect(slots[2]).toBe('fresh_1')
    expect(slots[3]).toBe('healed_1')
    expect(slots[4]).toBe('fresh_2')
    expect(slots[5]).toBe('healed_2')
  })
})

// ─── parseSlotType ────────────────────────────────────────────────────────────

describe('parseSlotType', () => {
  it('before_skin → kind before, no session_number', () => {
    const p = parseSlotType('before_skin')
    expect(p.kind).toBe('before')
    expect(p.session_number).toBeNull()
  })

  it('reference → kind reference, no session_number', () => {
    const p = parseSlotType('reference')
    expect(p.kind).toBe('reference')
    expect(p.session_number).toBeNull()
  })

  it('fresh_1 → kind fresh, session_number 1', () => {
    const p = parseSlotType('fresh_1')
    expect(p.kind).toBe('fresh')
    expect(p.session_number).toBe(1)
  })

  it('fresh_12 → kind fresh, session_number 12', () => {
    const p = parseSlotType('fresh_12')
    expect(p.kind).toBe('fresh')
    expect(p.session_number).toBe(12)
  })

  it('healed_2 → kind healed, session_number 2', () => {
    const p = parseSlotType('healed_2')
    expect(p.kind).toBe('healed')
    expect(p.session_number).toBe(2)
  })

  it('healed_7 → kind healed, session_number 7', () => {
    const p = parseSlotType('healed_7')
    expect(p.kind).toBe('healed')
    expect(p.session_number).toBe(7)
  })

  it('unknown string → treated as reference kind', () => {
    const p = parseSlotType('something_unknown')
    expect(p.kind).toBe('reference')
    expect(p.session_number).toBeNull()
  })
})

// ─── computeHealedDueDate ─────────────────────────────────────────────────────

describe('computeHealedDueDate', () => {
  it('adds exactly 42 days (6 weeks)', () => {
    const sessionDate = new Date('2026-01-01T00:00:00Z')
    const due = computeHealedDueDate(sessionDate)
    // 2026-01-01 + 42 days = 2026-02-12
    expect(due.toISOString().slice(0, 10)).toBe('2026-02-12')
  })

  it('does not mutate the input date', () => {
    const sessionDate = new Date('2026-06-15T12:00:00Z')
    const originalTime = sessionDate.getTime()
    computeHealedDueDate(sessionDate)
    expect(sessionDate.getTime()).toBe(originalTime)
  })

  it('handles leap year correctly', () => {
    // 2024-02-14 + 42 days = 2024-03-27
    const sessionDate = new Date('2024-02-14T00:00:00Z')
    const due = computeHealedDueDate(sessionDate)
    expect(due.toISOString().slice(0, 10)).toBe('2024-03-27')
  })

  it('due date is always after session date', () => {
    const sessionDate = new Date()
    const due = computeHealedDueDate(sessionDate)
    expect(due.getTime()).toBeGreaterThan(sessionDate.getTime())
  })
})

'use server'

