import { logger } from '@/lib/logger'
import type { ProjectStatus } from '@/lib/supabase/types'

// ─── Validation schemas ───────────────────────────────────────────────────────

const ProjectIdArray = z
  .array(z.string().uuid())
  .min(1, 'At least one project required')
  .max(100, 'Maximum 100 projects per bulk action')

const BulkStatusSchema = z.object({
  projectIds: ProjectIdArray,
  newStatus: z.enum([
    'planning',
    'deposit_paid',
    'active',
    'healing',
    'completed',
    'on_hold',
    'cancelled',
  ]),
})

// ─── Types ────────────────────────────────────────────────────────────────────

type BulkActionResult = { ok: true } | { ok: false; error: string }

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Verify all project IDs belong to the authenticated studio.
 * Returns the ids that were NOT found (i.e. foreign or non-existent).
 */
async function verifyProjectsInStudio(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  projectIds: string[],
): Promise<string[]> {
  const { data, error } = await supabase
    .from('projects')
    .select('id')
    .eq('studio_id', studioId)
    .in('id', projectIds)

  if (error) return projectIds // assume all foreign if query fails
  const found = new Set((data ?? []).map((r) => r.id))
  return projectIds.filter((id) => !found.has(id))
}

// ─── Bulk archive ─────────────────────────────────────────────────────────────

/**
 * Archive multiple projects at once.
 * Role required: owner or admin.
 */
export async function bulkArchiveProjectsAction(
  projectIds: string[],
): Promise<BulkActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role
  if (role !== 'owner' && role !== 'admin') {
    return { ok: false, error: 'Only owners and admins can archive projects' }
  }

  const parsed = ProjectIdArray.safeParse(projectIds)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid project IDs' }
  }

  const supabase = await createClient()

  // Verify all IDs belong to this studio
  const foreignIds = await verifyProjectsInStudio(supabase, auth.studioId, parsed.data)
  if (foreignIds.length > 0) {
    return { ok: false, error: 'One or more projects not found in your studio' }
  }

  const errors: string[] = []

  for (const projectId of parsed.data) {
    const { error } = await supabase.rpc('advance_project_status', {
      p_project_id: projectId,
      p_new_status: 'cancelled' as ProjectStatus,
      p_force: false,
    })
    if (error) {
      logger.warn(
        { projectId, studioId: auth.studioId, error: error.message },
        'bulkArchiveProjectsAction: rpc failed for project',
      )
      errors.push(projectId)
    }
  }

  revalidatePath('/projects')

  if (errors.length > 0) {
    const failed = errors.length
    const total = parsed.data.length
    return {
      ok: false,
      error: `${failed} of ${total} projects could not be archived. The rest were updated.`,
    }
  }

  logger.info(
    { studioId: auth.studioId, count: parsed.data.length, actorId: auth.user.id },
    'bulkArchiveProjectsAction: success',
  )

  return { ok: true }
}

// ─── Bulk status change ───────────────────────────────────────────────────────

/**
 * Change the status of multiple projects.
 * Role required: owner or admin (or receptionist for non-archive targets).
 */
export async function bulkChangeProjectStatusAction(
  projectIds: string[],
  newStatus: string,
): Promise<BulkActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role

  // Validate inputs
  const parsed = BulkStatusSchema.safeParse({ projectIds, newStatus })
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  // Archive target requires owner/admin
  if (parsed.data.newStatus === 'cancelled' && role !== 'owner' && role !== 'admin') {
    return { ok: false, error: 'Only owners and admins can archive projects' }
  }

  // Other status changes allow receptionist role
  const allowedRoles = ['owner', 'admin', 'receptionist'] as const
  if (!allowedRoles.includes(role as (typeof allowedRoles)[number])) {
    return { ok: false, error: 'Insufficient permissions for status change' }
  }

  const supabase = await createClient()

  // Verify all IDs belong to this studio
  const foreignIds = await verifyProjectsInStudio(
    supabase,
    auth.studioId,
    parsed.data.projectIds,
  )
  if (foreignIds.length > 0) {
    return { ok: false, error: 'One or more projects not found in your studio' }
  }

  const errors: string[] = []

  for (const projectId of parsed.data.projectIds) {
    const { error } = await supabase.rpc('advance_project_status', {
      p_project_id: projectId,
      p_new_status: parsed.data.newStatus as ProjectStatus,
      p_force: false,
    })
    if (error) {
      logger.warn(
        { projectId, newStatus: parsed.data.newStatus, error: error.message },
        'bulkChangeProjectStatusAction: rpc failed for project',
      )
      errors.push(projectId)
    }
  }

  revalidatePath('/projects')

  if (errors.length > 0) {
    const failed = errors.length
    const total = parsed.data.projectIds.length
    return {
      ok: false,
      error: `${failed} of ${total} projects could not be updated. The rest were changed.`,
    }
  }

  logger.info(
    {
      studioId: auth.studioId,
      count: parsed.data.projectIds.length,
      newStatus: parsed.data.newStatus,
      actorId: auth.user.id,
    },
    'bulkChangeProjectStatusAction: success',
  )

  return { ok: true }
}

