// ─── Formatters ───────────────────────────────────────────────────────────────

function fmtCurrency(cents: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(cents / 100)
}

function fmtDate(iso: string | null): string {
  if (!iso) return '—'
  try {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    }).format(new Date(iso))
  } catch {
    return iso
  }
}

function fmtStatus(status: string): string {
  const map: Record<string, string> = {
    planning: 'Planning',
    deposit_paid: 'Deposit Paid',
    active: 'Active',
    healing: 'Healing',
    completed: 'Completed',
    on_hold: 'On Hold',
    cancelled: 'Archived',
  }
  return map[status] ?? status
}

function fmtSlotLabel(slotType: string): string {
  if (slotType === 'before_skin') return 'Before'
  if (slotType === 'reference') return 'Reference'
  const m = /^(fresh|healed)_(\d+)$/.exec(slotType)
  if (m) return `${m[1] === 'fresh' ? 'Fresh' : 'Healed'} #${m[2]}`
  return slotType
}

