'use client'

import { useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import type { ViewMode } from './ProjectsListClient'

// ─── Types ────────────────────────────────────────────────────────────────────

interface ProjectsKeyboardShortcutsProps {
  searchInputId: string
  viewMode: ViewMode
  onViewChange: (mode: ViewMode) => void
  onToggleFilters: () => void
  onToggleSelect: (multi: boolean) => void
  onArchiveSelected: () => void
  onOpenOverlay: () => void
  onClearSelection: () => void
  disabled?: boolean
}

// ─── g-chord pattern — mirrors CalendarView.tsx approach ─────────────────────
// We track the last key + timestamp. If the next key arrives within 500ms,
// we treat the pair as a chord. This matches the V+B/L/G/T pattern.

const CHORD_TIMEOUT_MS = 500

const VIEW_CHORD: Record<string, ViewMode> = {
  b: 'board',
  l: 'list',
  g: 'gallery',
  t: 'timeline',
}

// ─── Component ────────────────────────────────────────────────────────────────

export function ProjectsKeyboardShortcuts({
  searchInputId,
  viewMode: _viewMode,
  onViewChange,
  onToggleFilters,
  onToggleSelect,
  onArchiveSelected,
  onOpenOverlay,
  onClearSelection,
}: ProjectsKeyboardShortcutsProps) {
  const router = useRouter()
  const lastKeyRef = useRef<string | null>(null)
  const lastKeyTimeRef = useRef<number>(0)

  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      // Ignore when focused on input / textarea / contenteditable
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return
      // Ignore modifier combos (except Shift which we handle explicitly)
      if (e.ctrlKey || e.metaKey || e.altKey) return

      const key = e.key.toLowerCase()
      const now = Date.now()

      // ── V-chord: V then B/L/G/T ───────────────────────────────────────────
      if (lastKeyRef.current === 'v' && now - lastKeyTimeRef.current < CHORD_TIMEOUT_MS) {
        const targetView = VIEW_CHORD[key]
        if (targetView) {
          e.preventDefault()
          onViewChange(targetView)
          lastKeyRef.current = null
          return
        }
      }

      // Record this key for chord detection
      lastKeyRef.current = key
      lastKeyTimeRef.current = now

      switch (key) {
        case 'p':
          e.preventDefault()
          router.push('/projects/new')
          break

        case '/':
          e.preventDefault()
          document.getElementById(searchInputId)?.focus()
          break

        case 'v':
          // Chord start — wait for second key; don't consume yet
          break

        case 'f':
          e.preventDefault()
          onToggleFilters()
          break

        case 'x':
          e.preventDefault()
          onToggleSelect(e.shiftKey)
          break

        case 'e': {
          // Navigate to focused card in edit mode
          e.preventDefault()
          const focused = document.querySelector('[data-project-id]:focus') as HTMLElement | null
          const projectId = focused?.dataset.projectId
          if (projectId) {
            router.push(`/projects/${projectId}?edit=1`)
          }
          break
        }

        case 'a':
          e.preventDefault()
          onArchiveSelected()
          break

        case '?':
          e.preventDefault()
          onOpenOverlay()
          break

        case 'escape':
          // Don't prevent default — allow modals to close via native Esc
          onClearSelection()
          break

        default:
          break
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [router, searchInputId, onViewChange, onToggleFilters, onToggleSelect, onArchiveSelected, onOpenOverlay, onClearSelection])

  // This component renders nothing — it's a pure side-effect handler
  return null
}

