import { useState, useTransition } from 'react'
import { X, Archive, ChevronDown, Download } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { cn } from '@/lib/utils'
import { bulkArchiveProjectsAction, bulkChangeProjectStatusAction } from '@/app/(app)/projects/bulk-actions'
import type { ProjectListItem } from '@/lib/projects/queries'

// ─── Status options ───────────────────────────────────────────────────────────

const STATUS_OPTIONS = [
  { value: 'planning', label: 'Planning' },
  { value: 'deposit_paid', label: 'Deposit Paid' },
  { value: 'active', label: 'Active' },
  { value: 'healing', label: 'Healing' },
  { value: 'completed', label: 'Completed' },
  { value: 'on_hold', label: 'On Hold' },
  { value: 'cancelled', label: 'Archive' },
] as const

// ─── CSV export helper ────────────────────────────────────────────────────────

function buildCsv(projects: ProjectListItem[]): string {
  const headers = ['Name', 'Client', 'Status', 'Sessions', 'Pool Balance (cents)', 'Artist', 'Created']
  const rows = projects.map((p) => {
    const client = p.client
      ? `${p.client.first_name}${p.client.last_name ? ` ${p.client.last_name}` : ''}`
      : ''
    const sessions = p.total_sessions_planned
      ? `${p.sessions_completed}/${p.total_sessions_planned}`
      : `${p.sessions_completed}`
    return [
      csvCell(p.name),
      csvCell(client),
      csvCell(p.status),
      csvCell(sessions),
      csvCell(String(p.deposit_pool_cents)),
      csvCell(p.primary_artist?.display_name ?? ''),
      csvCell(p.created_at),
    ].join(',')
  })
  return [headers.join(','), ...rows].join('\n')
}

function csvCell(value: string): string {
  // Escape double-quotes and wrap in quotes if special chars present
  if (/[",\n\r]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`
  }
  return value
}

function downloadCsv(csv: string, filename: string): void {
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.click()
  URL.revokeObjectURL(url)
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface BulkActionsBarProps {
  selectedIds: string[]
  allProjects: ProjectListItem[]
  onClearSelection: () => void
}

// ─── Component ────────────────────────────────────────────────────────────────

export function BulkActionsBar({
  selectedIds,
  allProjects,
  onClearSelection,
}: BulkActionsBarProps) {
  const [isPending, startTransition] = useTransition()
  const [showArchiveConfirm, setShowArchiveConfirm] = useState(false)

  if (selectedIds.length === 0) return null

  const selectedProjects = allProjects.filter((p) => selectedIds.includes(p.id))

  const handleArchive = () => {
    startTransition(async () => {
      const result = await bulkArchiveProjectsAction(selectedIds)
      if (!result.ok) {
        toast.error(result.error)
      } else {
        toast.success(`${selectedIds.length} project${selectedIds.length !== 1 ? 's' : ''} archived`)
        onClearSelection()
      }
    })
    setShowArchiveConfirm(false)
  }

  const handleStatusChange = (newStatus: string) => {
    startTransition(async () => {
      const result = await bulkChangeProjectStatusAction(selectedIds, newStatus)
      if (!result.ok) {
        toast.error(result.error)
      } else {
        const label = STATUS_OPTIONS.find((o) => o.value === newStatus)?.label ?? newStatus
        toast.success(`Status updated to ${label}`)
        onClearSelection()
      }
    })
  }

  const handleExportCsv = () => {
    const csv = buildCsv(selectedProjects)
    const date = new Date().toISOString().slice(0, 10)
    downloadCsv(csv, `inkos-projects-${date}.csv`)
    toast.success(`Exported ${selectedIds.length} project${selectedIds.length !== 1 ? 's' : ''}`)
  }

  return (
    <>
      {/* Bulk bar — fixed at bottom of viewport */}
      <div
        className={cn(
          'fixed bottom-6 left-1/2 -translate-x-1/2 z-50',
          'flex items-center gap-2 rounded-xl border border-[var(--color-border)]',
          'bg-[var(--color-onyx)] text-[var(--color-bone)]',
          'px-4 py-2.5 shadow-[var(--shadow-lift)]',
          'transition-all duration-150 ease-out',
        )}
        role="toolbar"
        aria-label={`${selectedIds.length} projects selected`}
      >
        {/* Count */}
        <span className="text-sm font-medium tabular-nums whitespace-nowrap">
          {selectedIds.length} {selectedIds.length === 1 ? 'project' : 'projects'} selected
        </span>

        <div className="w-px h-4 bg-[var(--color-bone)]/20 mx-1 shrink-0" />

        {/* Archive */}
        <Button
          size="sm"
          variant="ghost"
          className="h-7 px-2.5 text-xs text-[var(--color-bone)] hover:bg-[var(--color-bone)]/10 hover:text-[var(--color-bone)] gap-1.5"
          onClick={() => setShowArchiveConfirm(true)}
          disabled={isPending}
        >
          <Archive className="h-3.5 w-3.5" aria-hidden="true" />
          Archive
        </Button>

        {/* Change status */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              size="sm"
              variant="ghost"
              className="h-7 px-2.5 text-xs text-[var(--color-bone)] hover:bg-[var(--color-bone)]/10 hover:text-[var(--color-bone)] gap-1"
              disabled={isPending}
            >
              Status
              <ChevronDown className="h-3 w-3" aria-hidden="true" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-40">
            {STATUS_OPTIONS.map(({ value, label }) => (
              <DropdownMenuItem
                key={value}
                onClick={() => handleStatusChange(value)}
              >
                {label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>

        {/* Export CSV */}
        <Button
          size="sm"
          variant="ghost"
          className="h-7 px-2.5 text-xs text-[var(--color-bone)] hover:bg-[var(--color-bone)]/10 hover:text-[var(--color-bone)] gap-1.5"
          onClick={handleExportCsv}
        >
          <Download className="h-3.5 w-3.5" aria-hidden="true" />
          CSV
        </Button>

        <div className="w-px h-4 bg-[var(--color-bone)]/20 mx-1 shrink-0" />

        {/* Clear */}
        <button
          onClick={onClearSelection}
          className="p-1 rounded hover:bg-[var(--color-bone)]/10 text-[var(--color-bone)]/60 hover:text-[var(--color-bone)] transition-colors"
          aria-label="Clear selection"
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>

      {/* Archive confirmation */}
      <AlertDialog open={showArchiveConfirm} onOpenChange={setShowArchiveConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Archive {selectedIds.length} project{selectedIds.length !== 1 ? 's' : ''}?
            </AlertDialogTitle>
            <AlertDialogDescription>
              This sets their status to Archived and hides them from the active list.
              Sessions and photos are preserved. You can restore individual projects from
              their detail page.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleArchive}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              Archive {selectedIds.length} project{selectedIds.length !== 1 ? 's' : ''}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

