  const [selectedIds, setSelectedIds] = useState<string[]>([])

  const handleToggleSelect = useCallback(
    (_multi: boolean) => {
      // Focus-based selection: find focused card's project id
      const focused = document.querySelector('[data-project-id]:focus') as HTMLElement | null
      const projectId = focused?.dataset.projectId
