    TABS.find((t) => t.id === initialTab)?.id ?? 'sessions'
  )
  const [showArchiveDialog, setShowArchiveDialog] = useState(false)
  const [showOverlay, setShowOverlay] = useState(false)
  const [isPending, startTransition] = useTransition()
  const activeTabRef = useRef<TabId>(TABS.find((t) => t.id === initialTab)?.id ?? 'sessions')

  const canAdmin = role === 'owner' || role === 'admin'

  // Keep ref in sync with state for keyboard handler closure
  useEffect(() => {
    activeTabRef.current = activeTab
  }, [activeTab])

  // ── Keyboard shortcuts ────────────────────────────────────────────────────
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return
      if (e.ctrlKey || e.metaKey || e.altKey) return

      const key = e.key.toLowerCase()

      switch (key) {
        case 'tab': {
          e.preventDefault()
          const currentIdx = TABS.findIndex((t) => t.id === activeTabRef.current)
          const nextIdx = (currentIdx + 1) % TABS.length
          const nextTab = TABS[nextIdx]
          if (nextTab) {
            setActiveTab(nextTab.id)
            activeTabRef.current = nextTab.id
            const url = new URL(window.location.href)
            url.searchParams.set('tab', nextTab.id)
            router.replace(url.pathname + url.search, { scroll: false })
          }
          break
        }
        case 'escape':
          router.push('/projects')
          break
        case 'e': {
          // Trigger click on the hero title edit button
          const editBtn = document.querySelector<HTMLButtonElement>(
            '[aria-label="Edit project name"]'
          )
          editBtn?.click()
          break
        }
        case '?':
          e.preventDefault()
          setShowOverlay(true)
          break
        default:
          break
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [router])

