import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import { slugify } from '@/lib/utils'
import type { PdfProjectData, PdfSession, PdfPhoto, PdfTransaction } from '@/lib/projects/pdf-template'

// ─── Dynamic import to keep bundle small ─────────────────────────────────────
async function renderProjectPdf(data: PdfProjectData): Promise<Buffer> {
  const { renderToBuffer } = await import('@react-pdf/renderer')
  const { ProjectPdfDocument } = await import('@/lib/projects/pdf-template')
  const element = ProjectPdfDocument({ data })
  return renderToBuffer(element)
}

// ─── Route handler ────────────────────────────────────────────────────────────

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id: projectId } = await params

  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return new Response('Unauthorized', { status: 401 })
  }

  // Rate limit — PDF generation is expensive
  const { success } = await authedRatelimit.limit(auth.user.id)
  if (!success) {
    return new Response('Too many requests', { status: 429 })
  }

  const supabase = await createClient()

  // Fetch project (RLS enforces studio membership)
  const { data: project, error: projectError } = await supabase
    .from('projects')
    .select(`
      id, studio_id, name, status,
      size, placement, style, color_mode,
      primary_artist_id, secondary_artist_ids, started_at, deposit_apply_rule,
      total_sessions_planned, total_price_cents, deposit_pool_cents, deposit_applied_cents,
      stalled_at, completed_at,
      client:clients!projects_client_id_fkey(
        id, first_name, last_name, phone
      ),
      primary_artist:artists!projects_primary_artist_id_fkey(
        id, display_name
      )
    `)
    .eq('id', projectId)
    .single()

  if (projectError || !project) {
    logger.warn({ projectId, error: projectError?.message }, 'export: project not found')
    return new Response('Project not found', { status: 404 })
  }

  // Verify studio membership (belt-and-suspenders; RLS handles this but explicit is safer)
  if (project.studio_id !== auth.studioId) {
    return new Response('Forbidden', { status: 403 })
  }

  // Fetch studio
  const { data: studio } = await supabase
    .from('studios')
    .select('name, logo_url')
    .eq('id', auth.studioId)
    .single()

  // Fetch sessions (bookings linked to project) — use actual column names from schema
  const { data: bookings } = await supabase
    .from('bookings')
    .select(`
      id, scheduled_at, session_number, status,
      price_cents, deposit_cents, duration_min,
      artist:artists!bookings_artist_id_fkey(display_name)
    `)
    .eq('project_id', projectId)
    .order('session_number', { ascending: true, nullsFirst: false })
    .order('scheduled_at', { ascending: true })

  // Fetch progress photos — use actual schema columns (kind, storage_path, display_order)
  const { data: rawPhotos } = await supabase
    .from('project_progress_photos')
    .select('kind, storage_path, display_order')
    .eq('project_id', projectId)
    .order('display_order', { ascending: true })

  // Fetch deposit transactions from the deposit transactions interface
  // (table may not exist in generated types yet — use unknown cast for forward compat)
  const { data: rawTransactions } = await (supabase as unknown as {
    from: (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          order: (col: string, opts: { ascending: boolean }) => Promise<{
            data: Array<{
              created_at: string
              type: string
              note: string | null
              amount_cents: number
            }> | null
          }>
        }
      }
    }
  }).from('project_deposit_transactions')
    .select('created_at, type, note, amount_cents')
    .eq('project_id', projectId)
    .order('created_at', { ascending: true })

  // Build sessions array
  const sessions: PdfSession[] = (bookings ?? []).map((b, i) => {
    const artistData = b.artist
    const artistName = Array.isArray(artistData)
      ? (artistData[0] as { display_name: string } | undefined)?.display_name ?? null
      : (artistData as { display_name: string } | null)?.display_name ?? null

    return {
      session_number: b.session_number,
      scheduled_at: b.scheduled_at,
      artist_name: artistName,
      duration_minutes: b.duration_min,
      price_cents: b.price_cents,
      deposit_applied_cents: b.deposit_cents ?? 0,
      status: b.status,
    }
  })

  // Build photos array (limit to first 12 for PDF grid) — map kind to slot_type-style label
  const kindToSlot: Record<string, string> = {
    before: 'before_skin',
    after: 'reference',
    healed: 'healed_1',
    progress: 'fresh_1',
  }
  const photos: PdfPhoto[] = (rawPhotos ?? []).slice(0, 12).map((p) => ({
    slot_type: kindToSlot[p.kind] ?? p.kind,
    photo_url: p.storage_path,
  }))

  // Build transactions
  const transactions: PdfTransaction[] = (rawTransactions ?? []).map((tx) => ({
    created_at: tx.created_at,
    type: (tx.type as PdfTransaction['type']) ?? 'received',
    note: tx.note,
    amount_cents: tx.amount_cents,
  }))

  // Compute next session
  const now = new Date().toISOString()
  const futureSession = sessions
    .filter((s) => s.scheduled_at > now && s.status !== 'cancelled')
    .sort((a, b) => a.scheduled_at.localeCompare(b.scheduled_at))[0]

  const completedCount = sessions.filter((s) => s.status === 'completed').length
  const poolBalance = Math.max(0, (project.deposit_pool_cents ?? 0) - (project.deposit_applied_cents ?? 0))

  const client = Array.isArray(project.client)
    ? (project.client[0] as { first_name: string; last_name: string | null; phone: string | null } | undefined) ?? null
    : (project.client as { first_name: string; last_name: string | null; phone: string | null } | null)

  const primaryArtist = Array.isArray(project.primary_artist)
    ? (project.primary_artist[0] as { display_name: string } | undefined) ?? null
    : (project.primary_artist as { display_name: string } | null)

  const data: PdfProjectData = {
    studioName: studio?.name ?? 'Studio',
    studioLogoUrl: studio?.logo_url ?? null,
    projectName: project.name,
    status: project.status,
    size: project.size,
    placement: project.placement,
    style: project.style,
    colorMode: project.color_mode,
    primaryArtist: primaryArtist?.display_name ?? null,
    secondaryArtists: [],
    startedAt: project.started_at,
    depositApplyRule: project.deposit_apply_rule,
    totalSessions: sessions.length,
    completedSessions: completedCount,
    totalSessionsPlanned: project.total_sessions_planned,
    nextSessionDate: futureSession?.scheduled_at ?? null,
    totalPriceCents: project.total_price_cents ?? 0,
    poolBalanceCents: poolBalance,
    sessions,
    photos,
    transactions,
    clientName: client ? `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}` : null,
    clientPhone: client?.phone ?? null,
    clientLtvCents: null,
    generatedAt: new Date().toISOString(),
  }

  try {
    const pdfBuffer = await renderProjectPdf(data)

    const slug = slugify(project.name)
    const dateStr = new Date().toISOString().slice(0, 10)
    const filename = `${slug}-${dateStr}.pdf`

    // Log audit event
    await logAuditAction(
      auth.user.id,
      'project.export_pdf',
      { type: 'project', id: projectId },
      null,
      auth.studioId,
    )

    return new Response(pdfBuffer, {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'private, no-store',
      },
    })
  } catch (err) {
    logger.error({ err, projectId }, 'export: PDF generation failed')
    return new Response('PDF generation failed', { status: 500 })
  }
}

