import { z } from 'zod'
import { revalidatePath } from 'next/cache'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type { ProjectStatus } from '@/lib/supabase/types'

// ─── RPC helper — advance_project_status is not in generated types yet ────────
// Use a typed wrapper so we don't spread `unknown` casts into business logic.
async function callAdvanceProjectStatus(
  supabase: Awaited<ReturnType<typeof createClient>>,
  projectId: string,
  newStatus: ProjectStatus,
): Promise<{ error: { message: string } | null }> {
  const client = supabase as unknown as {
    rpc: (
      fn: string,
      args: Record<string, unknown>,
    ) => Promise<{ error: { message: string } | null }>
  }
  return client.rpc('advance_project_status', {
    p_project_id: projectId,
    p_new_status: newStatus,
    p_force: false,
  })
}

